+// Temporary diagnostic only: the service and transport clocks stay unchanged.
+struct AdmissionDiagnostic {
+    case: &'static str,
+    offline_face: Option<bool>,
+    mode: String,
+    started: std::time::Instant,
+    phases: Vec<(&'static str, u64, u64)>,
+    counts_before: [u64; 8],
+    control: Option<serde_json::Value>,
+}
+
+impl AdmissionDiagnostic {
+    fn new(case: &'static str, offline_face: Option<bool>) -> Self {
+        let mut diagnostic = Self {
+            case,
+            offline_face,
+            mode: std::env::var("EXPRESSION_ADMISSION_PROBE").unwrap_or_default(),
+            started: std::time::Instant::now(),
+            phases: Vec::with_capacity(8),
+            counts_before: [0; 8],
+            control: None,
+        };
+        diagnostic.mark("pre_publish");
+        diagnostic
+    }
+
+    fn mark(&mut self, phase: &'static str) {
+        self.phases.push((
+            phase,
+            runtime::unix_ms(),
+            self.started.elapsed().as_micros() as u64,
+        ));
+    }
+
+    fn counts(counts: &runtime::Counts) -> [u64; 8] {
+        [
+            counts.accepted,
+            counts.refused,
+            counts.input_errors,
+            counts.output_errors,
+            counts.dropped,
+            counts.steps,
+            counts.longest_step_us,
+            counts.records_lost,
+        ]
+    }
+
+    fn before_step(&mut self, bus: &Bus, service: &runtime::Service) {
+        let hold = matches!(
+            (self.mode.as_str(), self.offline_face),
+            ("expired_fresh", None) | ("expired_offline_true", Some(true))
+        );
+        if hold {
+            use std::time::{Duration, Instant};
+            let header = bus
+                .latest(VoiceTiming::TOPIC)
+                .expect("ADMISSION_SETUP: retained header read")
+                .expect("ADMISSION_SETUP: retained voice header missing")
+                .header;
+            let mut observer = bus
+                .subscribe_typed(VoiceTiming::TOPIC, "admission_probe", VoiceTiming::TYPE)
+                .expect("ADMISSION_SETUP: observer subscription");
+            let before = observer.expired();
+            let began = Instant::now();
+            let hold_started_ms = runtime::unix_ms();
+            while !header.expired_at(runtime::unix_ms()) {
+                assert!(
+                    began.elapsed() < Duration::from_secs(5),
+                    "ADMISSION_SETUP: expiry observation watchdog"
+                );
+                std::thread::sleep(Duration::from_millis(1));
+            }
+            let expiry_observed_ms = runtime::unix_ms();
+            let received = observer
+                .recv(Duration::ZERO)
+                .expect("ADMISSION_SETUP: observer receive");
+            let statistics = observer.statistics();
+            assert!(
+                received.is_none() && statistics.expired > before,
+                "ADMISSION_SETUP: observer did not reject the expired header"
+            );
+            let retained = bus
+                .latest(VoiceTiming::TOPIC)
+                .expect("ADMISSION_SETUP: final retained header read")
+                .expect("ADMISSION_SETUP: final retained voice missing");
+            assert_eq!(
+                retained.header, header,
+                "ADMISSION_SETUP: retained header changed"
+            );
+            assert!(
+                expiry_observed_ms >= hold_started_ms && retained.expired,
+                "ADMISSION_SETUP: wall clock or expiry changed"
+            );
+            self.control = Some(serde_json::json!({
+                "hold_started_ms": hold_started_ms,
+                "expiry_observed_ms": expiry_observed_ms,
+                "expired_when_hold_started": header.expired_at(hold_started_ms),
+                "header": header,
+                "observer_only": true,
+                "observer_expired_before": before,
+                "observer_expired_after": statistics.expired,
+                "observer_received": statistics.received,
+                "observer_wrong_type": statistics.wrong_type,
+                "observer_datagrams": statistics.datagrams,
+            }));
+            eprintln!(
+                "EXPRESSION_ADMISSION_GATE {}",
+                serde_json::json!({
+                    "case": self.case,
+                    "offline_face": self.offline_face,
+                    "mode": self.mode,
+                    "control": self.control,
+                })
+            );
+        }
+        self.counts_before = Self::counts(&service.counts);
+        self.mark("pre_step");
+    }
+
+    fn record(
+        &mut self,
+        bus: &Bus,
+        service: &runtime::Service,
+        output: &lamp_expression::Output,
+        injected_wall_ms: u64,
+    ) {
+        self.mark("post_step");
+        // Header I/O and printing happen after the normal admission path.
+        let headers: Vec<_> = [VoiceTiming::TOPIC, JointState::TOPIC]
+            .into_iter()
+            .map(|topic| match bus.latest(topic) {
+                Ok(Some(message)) => {
+                    let ages: Vec<_> = self
+                        .phases
+                        .iter()
+                        .map(|(phase, wall_ms, elapsed_us)| {
+                            serde_json::json!({
+                                "phase": phase,
+                                "real_wall_ms": wall_ms,
+                                "host_elapsed_us": elapsed_us,
+                                "signed_age_ms": i128::from(*wall_ms)
+                                    - i128::from(message.header.at_unix_ms),
+                                "expired_at_saved_phase": message.header.expired_at(*wall_ms),
+                            })
+                        })
+                        .collect();
+                    serde_json::json!({
+                        "topic": topic,
+                        "header": message.header,
+                        "expired_when_read_after_step": message.expired,
+                        "read_completed_real_ms": runtime::unix_ms(),
+                        "phase_ages": ages,
+                    })
+                }
+                Ok(None) => serde_json::json!({"topic": topic, "error": "no retained header"}),
+                Err(error) => serde_json::json!({"topic": topic, "error": error.to_string()}),
+            })
+            .collect();
+        eprintln!(
+            "EXPRESSION_ADMISSION {}",
+            serde_json::json!({
+                "case": self.case,
+                "offline_face": self.offline_face,
+                "mode": self.mode,
+                "injected_wall_ms": injected_wall_ms,
+                "injected_monotonic_us": 10_000_000,
+                "transport_grace_ms": lamp_bus::EXPIRY_GRACE_MS,
+                "headers": headers,
+                "counter_fields": ["accepted", "refused", "input_errors", "output_errors",
+                    "dropped", "steps", "longest_step_us", "records_lost"],
+                "service_counts_before": self.counts_before,
+                "service_counts_after": Self::counts(&service.counts),
+                "body_present": output.body.is_some(),
+                "light_present": output.light.is_some(),
+                "state": &output.state,
+                "control": self.control,
+                "service_subscriber_expiry_counters": "private; not observed",
+            })
+        );
+    }
+}
+
